src.renderinti:
public static function renderinti( $flow, $payload, $flow_class = 'service', $recipient = '' ) {
	$r = self::paskelbtas( $flow );
	if ( ! $r ) { return array( 'subject' => '', 'html' => '' ); }

	$subject = self::pakeisti( $r['subject'], $payload );
	$body    = self::blokai_i_html( $r['blocks'], $payload );
	if ( trim( $body ) === '' ) { return array( 'subject' => $subject, 'html' => '' ); }

	$html = Petshop_Email_Layout::wrap( array(
		'subject'    => $subject,
		'preheader'  => self::pakeisti( $r['preheader'], $payload ),
		'body'       => $body,
		'flow_class' => $flow_class,
		'email'      => $recipient,
		'reason'     => self::pakeisti( $r['reason'], $payload ),
	) );
	return array( 'subject' => $subject, 'html' => $html );
}

src.perziura:
public static function perziura( $flow, $version = 0, $payload = array() ) {
	global $wpdb;
	$T = self::lentele();
	if ( $version ) {
		$r = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM `$T` WHERE flow=%s AND version=%d", $flow, (int) $version ), ARRAY_A );
	} else {
		$r = self::juodrastis( $flow );
		if ( ! $r ) { $r = self::paskelbtas( $flow ); }
	}
	if ( ! $r ) {
		/* Nei juodrascio, nei paskelbto — rodom KODO SABLONA, kad perziura
		   veiktu visiems 20 srautu, o ne tik perkeltiems. */
		$fl = class_exists( 'Petshop_Email_Dispatch' ) ? Petshop_Email_Dispatch::flows() : array();
		if ( ! isset( $fl[ $flow ] ) ) { return array( 'ok' => false, 'klaida' => 'Nezinomas srautas' ); }
		$pvz2 = wp_parse_args( $payload, self::pavyzdinis_payload( $flow ) );
		$rf = Petshop_Email_Dispatch::render( $flow, $pvz2, array(
			'flow_class' => $fl[ $flow ]['class'], 'recipient_email' => 'pavyzdys@petshop.lt' ) );
		if ( empty( $rf['html'] ) ) { return array( 'ok' => false, 'klaida' => 'Sablonas negrazino turinio' ); }
		return array( 'ok' => true, 'saltinis' => 'kodo sablonas', 'subject' => $rf['subject'], 'html' => $rf['html'] );
	}
	$blocks = isset( $r['blocks'] ) ? $r['blocks'] : json_decode( (string) $r['blocks_json'], true );
	if ( ! is_array( $blocks ) ) { $blocks = array(); }

	$pvz = wp_parse_args( $payload, self::pavyzdinis_payload( $flow ) );
	$subject = self::pakeisti( $r['subject'], $pvz );
	$body    = self::blokai_i_html( $blocks, $pvz );
	$flows   = class_exists( 'Petshop_Email_Dispatch' ) ? Petshop_Email_Dispatch::flows() : array();
	$fc      = isset( $flows[ $flow ]['class'] ) ? $flows[ $flow ]['class'] : 'service';

	return array(
		'ok'      => true,
		'saltinis'=> $version ? ( 'versija v' . (int) $version ) : ( self::juodrastis( $flow ) ? 'juodrastis' : 'paskelbta' ),
		'subject' => $subject,
		'html'    => Petshop_Email_Layout::wrap( array(
			'subject'    => $subject,
			'preheader'  => self::pakeisti( $r['preheader'], $pvz ),
			'body'       => $body,
			'flow_class' => $fc,
			'email'      => 'pavyzdys@petshop.lt',
			'reason'     => self::pakeisti( $r['reason'], $pvz ),
		) ),
	);
}

src.paskelbtas:
public static function paskelbtas( $flow ) {
	global $wpdb;
	$T = self::lentele();
	if ( $wpdb->get_var( "SHOW TABLES LIKE '$T'" ) !== $T ) { return null; }
	$r = $wpdb->get_row( $wpdb->prepare(
		"SELECT * FROM `$T` WHERE flow=%s AND status='published' ORDER BY version DESC LIMIT 1", $flow
	), ARRAY_A );
	if ( ! $r ) { return null; }
	$r['blocks'] = json_decode( (string) $r['blocks_json'], true );
	if ( ! is_array( $r['blocks'] ) ) { $r['blocks'] = array(); }
	return $r;
}

