src.uztikrinti_renderi:
public static function uztikrinti_renderi() {
	$f = self::renderio_failas();
	$kodas = "<?php\n"
		. "/** Petshop laisku universalus renderis. Ikeliamas is Petshop_Email_Dispatch::render(). */\n"
		. "if ( ! defined( 'ABSPATH' ) ) { exit; }\n"
		. "\$ps_flow = isset( \$flow ) ? \$flow : Petshop_Laiskai_Turinys::dabartinis_flow();\n"
		. "\$ps_out  = Petshop_Laiskai_Turinys::renderinti(\n"
		. "\t\$ps_flow,\n"
		. "\tisset( \$payload ) ? (array) \$payload : array(),\n"
		. "\tisset( \$flow_class ) ? \$flow_class : 'service',\n"
		. "\tisset( \$recipient ) ? \$recipient : ''\n"
		. ");\n"
		. "\$subject = \$ps_out['subject'];\n"
		. "echo \$ps_out['html'];\n";
	if ( file_exists( $f ) && md5_file( $f ) === md5( $kodas ) ) { return 'jau_yra'; }
	if ( ! is_dir( dirname( $f ) ) ) { wp_mkdir_p( dirname( $f ) ); }
	if ( @token_get_all( $kodas, TOKEN_PARSE ) === false ) { return 'SINTAKSE'; }
	file_put_contents( $f, $kodas );
	return ( md5_file( $f ) === md5( $kodas ) ) ? 'irašyta' : 'KLAIDA';
}
